std::size_t ngroups = binfo->ngroups;
std::size_t nbits = binfo->nbits;
for (std::size_t i = 0; i < ngroups; ++i) {
    bitmap_t group = bitmap[i];
    bitmap_t full_mask;
    if (i + 1 == ngroups) {
        std::size_t rem = nbits & binfo->group_mask; // nbits % (1 << group_shift)
        if (rem == 0) {
            full_mask = static_cast<bitmap_t>(-1);
        } else {
            full_mask = (static_cast<bitmap_t>(1) << rem) - 1;
        }
    } else {
        full_mask = static_cast<bitmap_t>(-1);
    }
    if ((group & full_mask) != full_mask) {
        return false;
    }
}
return true;

